const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([11.184384, 35.114837]);
  const region = point.buffer(5000); // 5km buffer around point

  const date1 = '2019-02-06';
  const date2 = '2022-02-14';

  // 2. Data Acquisition for both dates
  const col1 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(point)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .filter(ee.Filter.eq('instrumentMode', 'IW'));

  const col2 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(point)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .filter(ee.Filter.eq('instrumentMode', 'IW'));

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`2019-02-06 images: ${size1}`);
  console.log(`2022-02-14 images: ${size2}`);

  // Check for empty collections - try wider date range
  if (size1 === 0 || size2 === 0) {
    console.log('Trying wider date range...');
    const col1_wide = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(point)
      .filterDate('2019-02-01', '2019-02-15')
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'));

    const col2_wide = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(point)
      .filterDate('2022-02-01', '2022-02-28')
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'));

    const size1_wide = col1_wide.size().getInfo();
    const size2_wide = col2_wide.size().getInfo();

    console.log(`Wider range - 2019: ${size1_wide}, 2022: ${size2_wide}`);

    if (size1_wide === 0 || size2_wide === 0) {
      console.log('No Sentinel-1 data available');
      console.log('<answer>C1</answer>');
      return;
    }

    var img1 = col1_wide.first();
    var img2 = col2_wide.first();
  } else {
    var img1 = col1.first();
    var img2 = col2.first();
  }

  // 3. Processing - Water detection using VV polarization
  const vv1 = img1.select('VV');
  const vv2 = img2.select('VV');

  // Water mask: VV < -15 dB typically indicates water
  const water1 = vv1.lt(-15);
  const water2 = vv2.lt(-15);

  // 4. Calculate water area
  const pixelArea = ee.Image.pixelArea();

  const waterArea1_dict = water1.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterArea2_dict = water2.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterArea1 = waterArea1_dict.get('VV').getInfo();
  const waterArea2 = waterArea2_dict.get('VV').getInfo();

  console.log(`2019 water area: ${(waterArea1 / 1e6).toFixed(2)} km²`);
  console.log(`2022 water area: ${(waterArea2 / 1e6).toFixed(2)} km²`);

  // 5. Validation & Final Answer
  if (waterArea1 === null || waterArea2 === null || 
      isNaN(waterArea1) || isNaN(waterArea2)) {
    console.log('Calculation failed - invalid results');
    console.log('<answer>C3</answer>');
    return;
  }

  if (waterArea2 > waterArea1) {
    console.log('Water extent was greater in 2022');
    console.log('<answer>A</answer>');
  } else {
    console.log('Water extent was NOT greater in 2022');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
